W=[
E('error','英 /ˈerə/；美 /ˈerər/','错误；差错；误差','原本想对准事实或目标，结果偏开了一点，甚至偏得很远。','经古法语 error 借拉丁 error / errōrem，后者来自 errāre“走偏”。不是英语 err 加表示人的 -or，所以不是“犯错的人”。',ER,'a spelling error 是拼写错误；an error message 是系统报错信息。测量中的 error 是结果与参考真值的偏差，不一定有人操作失误。','human error；an error message；a spelling error；measurement error。','mistake 更常说人的失误；error 也广用于程序和测量，但两者在一般错误义上重叠。',('I found an error in the total at the bottom of the page.','我发现页底合计数里有一处错误。'),('The app displays an error message when the file cannot be opened.','文件无法打开时，应用会显示报错信息。'),('The instrument has a small measurement error.','这台仪器存在轻微的测量误差。'),sources=['https://www.etymonline.com/word/error']),
E('err','英 /ɜː/；美 /er/，也读 /ɜːr/','犯错；判断失误','判断或行动没有落在正确的位置上。','经古法语 errer 接拉丁 errāre，最早的走偏、迷路义发展成犯错。它是动词，不是 error 的随意缩写。',R+[['古法语 errer → 中古英语 erren → 英语 err','走偏、犯错']],'普通“弄错了”常说 make a mistake；err 较正式。err on the side of caution 是宁愿偏谨慎些，防止冒进，并不承认已经作出错误决定。','err in doing something；err on the side of caution；to err。','error 是名词；err 是动词。err 与表示犹豫的 er 可能同音，但不是同一个来源和用法。',('The committee erred in relying on outdated figures.','委员会错在依赖了过时的数据。'),('When the forecast is uncertain, we err on the side of caution.','预报不确定时，我们宁愿谨慎一些。'),sources=['https://www.etymonline.com/word/err','https://www.oxfordlearnersdictionaries.com/definition/english/err']),
E('erratic','/ɪˈrætɪk/','不稳定的；无规律的；飘忽的；冰川漂砾','像路线忽左忽右，让人猜不出下一步。','借法语 erratique，也可直接接拉丁 errāticus“漂泊的”。现代形容词保留了没有稳定走向的感觉，地质学名词则形容被搬到异地的岩石。',ET,'erratic behaviour 是行为忽然变化、难预测；erratic performance 是表现时好时坏。地质学 an erratic 是被冰川搬运后留下的漂砾，石头并不是自己乱走。','erratic behaviour；an erratic performance；an erratic signal；a glacial erratic。','erroneous 说内容错误；erratic 说规律不稳定。一次错误不必然意味着长期 erratic。',('The old engine gave an erratic performance.','这台旧发动机运转时好时坏。'),('Her internet connection has been erratic all week.','她的网络连接这一周一直很不稳定。'),('The guide pointed out a large glacial erratic beside the trail.','向导指出了步道旁的一块大冰川漂砾。'),sources=['https://www.etymonline.com/word/erratic','https://www.nps.gov/articles/erratics.htm']),
E('erratically','/ɪˈrætɪkli/','不稳定地；忽快忽慢地；无规律地','事情的节奏、方向或表现不断跳动，难以预测。','erratic 加 -ally；通常把 -ically 读为 /ɪkli/，不是逐个元音拉长。',ET+[['英语 erratic + -ally → erratically','以不稳定、无规律的方式']],'drive erratically 是开得忽左忽右、忽快忽慢等不稳；a machine behaves erratically 是机器表现不正常、不规律。具体是哪一种变化由上下文补足。','behave erratically；move erratically；fluctuate erratically。','incorrectly 是做法或结果不正确；erratically 重点在不稳定、缺少可预测规律。',('The cursor moved erratically across the screen.','光标在屏幕上不规则地跳动。'),('Sales fluctuated erratically during the first few months.','最初几个月的销售额上下波动，很不稳定。'),sources=['https://en.wiktionary.org/wiki/erratically#English']),
E('erroneous','英 /ɪˈrəʊniəs/；美 /ɪˈroʊniəs/','错误的；不正确的','看起来像一个判断或事实，实际却偏离了真相。','经法语或直接借拉丁 errōneus；拉丁词义从游荡、走偏引申到错误。不是把英语 error 直接加 -neous。',EO,'常修饰 assumption、belief、information、conclusion，语气较正式。an erroneous conclusion 是结论有误，不是在说说话的人品格邪恶。','an erroneous assumption；erroneous information；an erroneous conclusion。','wrong 更日常且用法广；erroneous 常用于信息、判断、推论的错误。',('The argument rests on an erroneous assumption.','这套论证建立在一个错误假设上。'),('The website published erroneous information about the event date.','网站发布的活动日期信息有误。'),sources=['https://www.etymonline.com/word/erroneous']),
E('erroneously','英 /ɪˈrəʊniəsli/；美 /ɪˈroʊniəsli/','错误地；误认为；误报地','本来想描述、判断或标记正确，却把事情弄错了。','erroneous 加 -ly，形成修饰判断、报道和分类等行为的副词。',EO+[['英语 erroneous + -ly → erroneously','以错误的判断或信息进行']],'erroneously reported 是报道有误；erroneously labelled 是标签或分类错误。它说明错误发生，不直接断言是故意造假。','erroneously assume；erroneously report；erroneously label。','falsely 在某些语境容易让人想到不真实的指控；erroneously 更突出出错本身，不必含欺骗意图。',('The package was erroneously labelled as fragile.','这个包裹被误贴上了易碎品标签。'),('Several newspapers erroneously reported that the exhibition had closed.','几家报纸误报展览已经关闭。'),sources=['https://en.wiktionary.org/wiki/erroneously#English']),
E('aberration','/ˌæbəˈreɪʃən/','异常；偏离常态的现象；像差','平常轨迹一直这样走，这一次突然偏了出去。','借拉丁 aberrātiō，接 aberrāre：ab-“离开” + errāre“游移、走偏”。不是从英语 aberrant 简单换尾就能代表全部历史。',R+[['拉丁 ab- + errāre → aberrāre → aberrātiō','离开通常路线；偏离'],['英语 aberration','异常、偏离常态；科学中的特定偏差']],'把一次糟糕表现称为 an aberration，是说它偏离了平时水平，不能代表常态。光学的 aberration 则是成像偏离理想情况的像差。','an isolated aberration；a temporary aberration；an aberration from the norm。','error 直接说错；aberration 先强调偏离平常模式，未必都是有人犯错。',('The coach called the heavy defeat an aberration.','教练说这场惨败只是一次反常表现。'),('The unusually warm week was an aberration in an otherwise cold winter.','那个异常温暖的星期，是这个寒冬里的一次反常现象。'),sources=['https://www.etymonline.com/word/aberration','https://www.merriam-webster.com/dictionary/aberration']),
E('errant','/ˈerənt/','走偏的；不规矩的；出游的（旧义）','某个人、动作或东西没有沿着应走的路线走。','法语两个同形 errer 的分词合流：一支接拉丁 errāre“走偏”，另一支接 iter“旅程”相关的后期拉丁旅行动词。出游义不能全部硬归为犯错。',[['两条并行来源：拉丁 errāre；另一支 iter 及后期拉丁 iterāre','走偏、犯错；旅程、旅行'],['古法语 errant；盎格鲁法语 erraunt','走偏的与出游的词形、意义交汇'],['中古英语 → 英语 errant','不规矩、偏离方向的；旧义出游的']],'an errant child 是不听规矩的孩子；an errant shot 是偏离目标的一击。历史文学中的出游骑士义强调四处行走，并不是说骑士每次都犯错。','an errant child；an errant shot；errant behaviour。','erratic 强调变化无规律；errant 强调偏离了应有的方向、位置或行为规范。',('An errant pass sent the ball into the crowd.','一次传偏的球飞进了人群。'),('She gathered an errant strand of hair behind her ear.','她把一缕不听话的头发拢到耳后。'),sources=['https://www.etymonline.com/word/errant','https://en.wiktionary.org/wiki/errant#English']),
E('erratum','/eˈrɑːtəm/；复数 errata /eˈrɑːtə/','文字或印刷错误；勘误项、勘误通知','书或文章已经发出，后来发现一处错，需要公开指出并改正。','借拉丁 errātum，是 errāre 的中性分词名词化，意为犯下的错误。errata 保留拉丁中性复数词尾，不是另一种错误。',R+[['拉丁 errātum，复数 errāta','错误之处；犯下的错误'],['英语 erratum / errata','出版、写作中的错误及相应勘误']],'期刊里的 an erratum 常指针对已发表文章的更正通知；书后的 errata 列出多项需改正之处。一般聊天中的打错字不必总用这个正式词。','publish an erratum；a list of errata；an erratum notice。','error 是任何错误；erratum/errata 特别常见于出版和正式勘误。',('The journal published an erratum correcting the figure label.','期刊发布了一则勘误，更正图中的标签。'),('A list of errata appears on the publisher’s website.','出版社网站上列出了勘误表。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/erratum','https://www.merriam-webster.com/dictionary/erratum'])
]
